def comb_sort(arr):
    gap = len(arr)
    sorting = True
    while gap > 1 or sorting:
        gap = max(1, int(gap / 1.3))
        sorting = False
        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorting = True
    return arr
```

