def eulerian_num(n, m):
    # Create a table to store values of Eulerian numbers
    A = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case
    A[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            if j == 0:
                A[i][j] = (i + 1) * A[i - 1][j]
            elif j == i:
                A[i][j] = (i) * A[i - 1][j - 1]
            else:
                A[i][j] = (i - j + 1) * A[i - 1][j] + (j + 1) * A[i - 1][j - 1]

    return A[n][m]
```

