def max_sub_array_sum_repeated(arr, n, k):
    # Calculate the sum of the original array
    total_sum = sum(arr)

    # Function to calculate the maximum subarray sum using Kadane's algorithm
    def kadanes_algorithm(array):
        max_ending_here = max_so_far = array[0]
        for x in array[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # Calculate maximum subarray sum in the original array
    max_sum_one = kadanes_algorithm(arr)

    # Calculate maximum subarray sum for the array repeated
    if k == 1:
        return max_sum_one
    elif k == 2:
        return max(max_sum_one, 
                   max_sum_one + total_sum + kadanes_algorithm(arr))

    # For more than 2 repetitions, we need to consider conjoined cases
    max_sum_two = max(max_sum_one, 
                      kadanes_algorithm(arr + arr), 
                      max_sum_one + total_sum + max(0, max_sum_one))

    # If total_sum is positive, we can add multiples of it
    if total_sum > 0:
        return max(max_sum_two, 
                   max_sum_one + (k - 2) * total_sum)
    else:
        return max_sum_two
```

