def max_sum_increasing_subseq(arr, n, i, k):
    # Prefix sum calculation for increasing subsequences
    prefix_sum = [0] * n
    for j in range(i + 1):
        max_sum = 0
        for l in range(j + 1):
            if arr[l] < arr[j]:
                max_sum = max(max_sum, prefix_sum[l])
        prefix_sum[j] = max_sum + arr[j]

    # Consider the kth element and calculate the maximum sum including it
    max_increasing_sum = prefix_sum[i]
    for j in range(i + 1, n):
        if arr[j] > arr[k]:
            max_increasing_sum = max(max_increasing_sum, prefix_sum[i] + arr[j])

    return max_increasing_sum
```

